import type { TLinkElement } from "platejs";

import { forwardRef } from "react";
import { type PlateElementProps, PlateElement } from "platejs/react";
import { getLinkAttributes } from "@platejs/link";

const TexturaLinkElement = forwardRef<HTMLAnchorElement, PlateElementProps<TLinkElement>>(
  (props, ref) => (
    <PlateElement
      ref={ref}
      as="a"
      {...props}
      attributes={{
        ...props.attributes,
        ...getLinkAttributes(props.editor, props.element),
        onMouseOver: (e: React.MouseEvent) => {
          e.stopPropagation();
        },
      }}
    >
      {props.children}
    </PlateElement>
  ),
);

TexturaLinkElement.displayName = "TexturaLinkElement";

export { TexturaLinkElement };
